import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(max(previous_limit, len(raw_csv)))
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    def is_numeric(value):
        try:
            float(value.strip())
            return True
        except ValueError:
            return False

    header_index = 0
    while header_index < len(records) and not records[header_index]:
        header_index += 1

    if header_index == len(records):
        return {"columns": [], "rows": []}

    if len(records[header_index]) != 2:
        for index in range(header_index + 1, min(len(records), header_index + 11)):
            row = records[index]
            if len(row) == 2:
                if any(value.strip() and not is_numeric(value) for value in row):
                    header_index = index
                break

    columns = list(records[header_index])
    rows = [list(row) for row in records[header_index + 1:]]
    width = max([len(columns)] + [len(row) for row in rows])

    existing = set(columns)
    while len(columns) < width:
        number = len(columns) + 1
        name = "column_{}".format(number)
        while name in existing:
            number += 1
            name = "column_{}".format(number)
        columns.append(name)
        existing.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
